<?php $af=$planActionForm;$verb=$af['operation']==='move'?'Move':'Copy'; ?>
<section class="calendar-panel workout-page" aria-labelledby="plan-action-title"><div class="workout-page-heading"><h2 id="plan-action-title"><?php echo esc_html($verb.' planned workout'); ?></h2><a class="control" href="<?php echo esc_url($af['context']['url']); ?>">Back to calendar</a></div>
<h3><?php echo esc_html($af['title']); ?></h3><p>Currently scheduled for <?php echo esc_html($af['source_date']); ?>.</p>
<?php if($af['operation']==='move'): ?><p>Choose a new date for this plan. Its instructions and linked structured workout stay attached.</p><?php else: ?><p>Create a separate planned workout on the selected date. The original plan and recorded session stay unchanged. A linked structured workout gets its own independent copy.</p><?php endif; ?>
<?php if($af['error']): ?><p role="alert"><?php echo esc_html($af['error']->get_error_message()); ?></p><p><a href="<?php echo esc_url($af['context']['url'].'&plan_action='.$af['operation'].'&source_plan='.$af['id']); ?>">Reload form</a></p><?php endif; ?>
<form class="plan-action-editor plan-editor" method="post" action="/?action=plan_transfer">
<?php foreach(array('plan_id'=>$af['id'],'operation'=>$af['operation'],'nonce'=>wp_create_nonce('swimlog_plan_'.$af['operation'].'_'.$af['id']),'revision'=>$af['revision'],'date'=>$af['context']['date'],'view'=>$af['context']['view'])as$key=>$value): ?><input type="hidden" name="<?php echo esc_attr($key); ?>" value="<?php echo esc_attr($value); ?>"><?php endforeach; ?>
<div class="plan-field plan-wide"><label for="plan-target-date">Target date</label><input id="plan-target-date" name="target_date" type="date" required min="<?php echo esc_attr(wp_date('Y-m-d')); ?>" max="2199-12-31" value="<?php echo esc_attr($af['target_date']); ?>"></div>
<div class="plan-actions plan-wide"><button><?php echo esc_html($verb.' workout'); ?></button><a class="control" href="<?php echo esc_url($af['context']['url']); ?>">Cancel</a></div></form></section>
